const j = $json;
const binary = $input.first().binary || {};
const errors = [];

const dateStr = (j.scheduled_date || '').toString().trim();
const timeStr = (j.scheduled_time || '').toString().trim();
const caption = (j.post_text || '').toString();
const slugRaw = (j.folder_slug || '').toString().trim();

// Date: strict YYYY-MM-DD and a real calendar date.
const dm = dateStr.match(/^(\d{4})-(\d{2})-(\d{2})$/);
if (!dm) {
  errors.push('Invalid scheduled date (use YYYY-MM-DD).');
} else {
  const year = Number(dm[1]);
  const month = Number(dm[2]);
  const day = Number(dm[3]);
  const parsed = new Date(Date.UTC(year, month - 1, day));
  const isRealDate =
    parsed.getUTCFullYear() === year &&
    parsed.getUTCMonth() === month - 1 &&
    parsed.getUTCDate() === day;

  if (!isRealDate) {
    errors.push('Invalid scheduled date (choose a real calendar date).');
  }
}

// Time: HH:MM, 24-hour.
const tm = timeStr.match(/^([01]?\d|2[0-3]):([0-5]\d)$/);
if (!tm) {
  errors.push('Invalid scheduled time (use 24-hour HH:MM, e.g. 18:00).');
}

// Post text must not be empty.
if (!caption.trim()) {
  errors.push('Post text is empty.');
}

// Images: 1–4 PNG/JPG files.
const keys = Object.keys(binary);
const allowedExt = ['png', 'jpg', 'jpeg'];

if (keys.length === 0) {
  errors.push('At least one image is required.');
}
if (keys.length > 4) {
  errors.push('No more than four images are allowed.');
}

for (const k of keys) {
  const b = binary[k] || {};
  const ext = (b.fileExtension || (b.fileName || '').split('.').pop() || '').toLowerCase();
  const mime = (b.mimeType || '').toLowerCase();
  const okExt = allowedExt.includes(ext);
  const okMime = mime === 'image/png' || mime === 'image/jpeg' || mime === 'image/jpg';

  if (!okExt && !okMime) {
    errors.push('Unsupported file type: ' + (b.fileName || k) + ' (only PNG/JPG allowed).');
  }
}

// Canonical package folder: YYYY-MM-DD_HHMM[__label]
const hhmm = tm ? (tm[1].padStart(2, '0') + tm[2]) : '0000';
const slug = slugRaw
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '');

let folderName = dateStr + '_' + hhmm;
if (slug) folderName += '__' + slug;

return [{
  json: {
    valid: errors.length === 0,
    errorMessage: errors.join(' '),
    folderName,
    caption,
    slug,
  },
}];

const folderId = $('Create Folder in Google Drive').first().json.id;
const caption = $('Validate Inputs with Code').first().json.caption;
const trigger = $('When Post Details Collected').first();
const binary = trigger.binary || {};

const items = [];

// tweet.txt from the caption
const txtBinary = await this.helpers.prepareBinaryData(
  Buffer.from(caption, 'utf8'),
  'tweet.txt',
  'text/plain',
);
items.push({ json: { fileName: 'tweet.txt', folderId }, binary: { data: txtBinary } });

// images -> 01.<ext>, 02.<ext> ...
const keys = Object.keys(binary).sort();
let i = 0;
for (const k of keys) {
  i++;
  const b = binary[k];
  const ext = (b.fileExtension || (b.fileName || '').split('.').pop() || 'png').toLowerCase();
  const idx = String(i).padStart(2, '0');
  items.push({ json: { fileName: idx + '.' + ext, folderId }, binary: { data: b } });
}

return items;
